// Mock the PayPal SDK loader.
jest.mock('@paypal/paypal-js', () => ({
  loadScript: jest.fn(),
}));

import { newSpecPage } from '@stencil/core/testing';
import { loadScript } from '@paypal/paypal-js';
import { ScOrderSubmit } from '../sc-order-submit';
import { ScPaypalButtons } from '../../../../ui/paypal-buttons/paypal-buttons';
import { flush, makePaypal } from '../../../../ui/paypal-buttons/test/helpers';
import { state as checkoutState, dispose as disposeCheckout } from '@store/checkout';
import { dispose as disposeCheckouts } from '@store/checkouts';
import { state as processorsState, dispose as disposeProcessors } from '@store/processors';
import { state as selectedProcessor, dispose as disposeSelectedProcessor } from '@store/selected-processor';
import { Checkout, Processor } from '../../../../../types';

const loadScriptMock = loadScript as jest.Mock;

/** A PayPal-only store: no Stripe, so sc-payment shows PayPal + its Credit Card tile. */
const seedPayPalOnlyStore = () => {
  processorsState.processors = [
    {
      id: 'paypalid',
      live_mode: false,
      recurring_enabled: true,
      processor_type: 'paypal',
      processor_data: { client_id: 'client-id', account_id: 'merchant-id' },
    },
  ] as unknown as Processor[];

  checkoutState.formId = 1;
  checkoutState.mode = 'test';
  checkoutState.currencyCode = 'usd';
  checkoutState.checkout = {
    id: 'checkout_1',
    live_mode: false,
    currency: 'usd',
    payment_method_required: true,
  } as Checkout;

  // What clicking the PayPal tile leaves in the store: `onScShow` writes `method = undefined`, not the store default ''.
  selectedProcessor.id = 'paypal';
  selectedProcessor.method = undefined;
};

/** What clicking the "Credit Card" tile does — see sc-payment-method-choice `onScShow`. */
const clickCreditCardTile = () => {
  selectedProcessor.id = 'paypal';
  selectedProcessor.manual = false;
  selectedProcessor.method = 'card';
};

/** Let a store write reach the DOM and any bootstrap it started settle. */
const settle = async page => {
  await page.waitForChanges();
  await flush();
  await page.waitForChanges();
};

const mountOrderSubmit = async () => {
  const page = await newSpecPage({
    components: [ScOrderSubmit, ScPaypalButtons],
    html: `<sc-order-submit></sc-order-submit>`,
  });
  await settle(page);
  return page;
};

const paypalButtons = page => page.root.querySelector('sc-paypal-buttons') as any;

describe('sc-order-submit', () => {
  beforeEach(() => {
    jest.clearAllMocks();
    // Downstream stores first so replayed watchers don't force-update the previous page's elements.
    disposeCheckouts();
    disposeSelectedProcessor();
    disposeProcessors();
    disposeCheckout();
  });

  it('boots the card funding source when the paypal Credit Card tile is picked', async () => {
    const paypal = makePaypal();
    loadScriptMock.mockResolvedValue(paypal);
    seedPayPalOnlyStore();
    const page = await mountOrderSubmit();

    expect(paypalButtons(page).buttons).toEqual(['paypal']);
    expect(loadScriptMock).toHaveBeenCalledTimes(1);
    expect(paypal.buttons[0].config.fundingSource).toBe('paypal');

    clickCreditCardTile();
    await settle(page);

    expect(paypalButtons(page).buttons).toEqual(['card']);
    expect(loadScriptMock).toHaveBeenCalledTimes(2);
    expect(paypal.buttons[1].config.fundingSource).toBe('card');
  });

  it('keeps the card button booted when the checkout is PATCHed mid-payment', async () => {
    const paypal = makePaypal();
    loadScriptMock.mockResolvedValue(paypal);
    seedPayPalOnlyStore();
    const page = await mountOrderSubmit();

    clickCreditCardTile();
    await settle(page);
    expect(loadScriptMock).toHaveBeenCalledTimes(2);

    // The card button's own createOrder PATCHes the checkout. If that nulled `method`, the parent would
    // swap to ['paypal'] and the `buttons` watcher would wipe the card iframe mid-payment.
    checkoutState.checkout = { ...checkoutState.checkout, updated_at: 2 } as Checkout;
    await settle(page);

    expect(paypalButtons(page).buttons).toEqual(['card']);
    expect(loadScriptMock).toHaveBeenCalledTimes(2);
  });
});
